def get_connected_components (grid ):
    """
    Identifies all connected components of non-zero pixels in a 2D grid.
    Returns a list of sets, where each set contains the (r, c) coordinates 
    of a single connected component.
    """
    rows =len (grid )
    cols =len (grid [0 ])
    visited =set ()
    components =[]

    for r in range (rows ):
        for c in range (cols ):
            if grid [r ][c ]!=0 and (r ,c )not in visited :
            # Start a new BFS/DFS to find the component
                component =set ()
                stack =[(r ,c )]
                visited .add ((r ,c ))

                while stack :
                    curr_r ,curr_c =stack .pop ()
                    component .add ((curr_r ,curr_c ))

                    # Check 4-connectivity (up, down, left, right)
                    for dr ,dc in [(0 ,1 ),(0 ,-1 ),(1 ,0 ),(-1 ,0 )]:
                        nr ,nc =curr_r +dr ,curr_c +dc 
                        if 0 <=nr <rows and 0 <=nc <cols :
                            if grid [nr ][nc ]!=0 and (nr ,nc )not in visited :
                                visited .add ((nr ,nc ))
                                stack .append ((nr ,nc ))
                components .append (component )
    return components

def transform (grid :list [list [int ]])->list [list [int ]]:
    rows =len (grid )
    cols =len (grid [0 ])

    def get_connected_components (grid ):
        visited =set ()
        components =[]
        for r in range (rows ):
            for c in range (cols ):
                if grid [r ][c ]!=0 and (r ,c )not in visited :
                    component =set ()
                    stack =[(r ,c )]
                    visited .add ((r ,c ))
                    while stack :
                        curr_r ,curr_c =stack .pop ()
                        component .add ((curr_r ,curr_c ))
                        for dr ,dc in [(0 ,1 ),(0 ,-1 ),(1 ,0 ),(-1 ,0 )]:
                            nr ,nc =curr_r +dr ,curr_c +dc 
                            if 0 <=nr <rows and 0 <=nc <cols :
                                if grid [nr ][nc ]!=0 and (nr ,nc )not in visited :
                                    visited .add ((nr ,nc ))
                                    stack .append ((nr ,nc ))
                    components .append (component )
        return components 

    def is_symmetric_and_hollow (component ):
    # Find bounding box
        min_r =min (r for r ,c in component )
        max_r =max (r for r ,c in component )
        min_c =min (c for r ,c in component )
        max_c =max (c for r ,c in component )

        h =max_r -min_r +1 
        w =max_c -min_c +1 

        # Check for symmetry within the bounding box
        for r_off in range (h ):
            for c_off in range (w ):
                if (min_r +r_off ,min_c +c_off )in component :
                # Check horizontal reflection: (r, c) -> (r, max_c - (c - min_c))
                    if (min_r +r_off ,max_c -(c_off ))not in component :
                        return False 
                        # Check vertical reflection: (r, c) -> (max_r - (r - min_r), c)
                    if (max_r -r_off ,min_c +c_off )not in component :
                        return False 

                        # Check hollowness: A component is hollow if its area is less than its bounding box area
                        # and it contains "holes" (0s) inside its bounding box.
                        # Based on the prompt, we want to keep 'frames'.
                        # A simple way to define 'hollow' in this context is that the component 
                        # does not fill its entire bounding box.
        if len (component )==h *w :
            return False # It's a solid block

        return True 

    components =get_connected_components (grid )
    output =[[0 for _ in range (cols )]for _ in range (rows )]

    for comp in components :
        if is_symmetric_and_hollow (comp ):
            for r ,c in comp :
                output [r ][c ]=grid [r ][c ]

    return output
